Prepare Translation Input:
// Pure data prep for the translation step. No prompt strings here —
// the Set node downstream owns the prompt template.
const input = $input.first().json.body || $input.first().json;
const ENGLISH_LOCALES = new Set(['us','gb','ca','au','nz','ie']);
const COUNTRY_NAMES = {
  us: 'United States', gb: 'United Kingdom', ca: 'Canada', au: 'Australia',
  nl: 'Netherlands', de: 'Germany', fr: 'France', be: 'Belgium',
  ch: 'Switzerland', at: 'Austria', ie: 'Ireland', se: 'Sweden',
  dk: 'Denmark', no: 'Norway', fi: 'Finland', es: 'Spain', it: 'Italy',
  pt: 'Portugal', pl: 'Poland', nz: 'New Zealand', sg: 'Singapore', in: 'India'
};

function cleanCareerTitle(raw) {
  if (!raw) return '';
  let cleaned = raw;
  cleaned = cleaned.replace(/\s*\([^)]*\)/g, '');
  cleaned = cleaned.split(/[—–|,]/)[0];
  cleaned = cleaned.replace(/\s+at\s+(?:a|an|the)\s+.+$/i, '');
  cleaned = cleaned.replace(/\s+to\s+(?:CEO|CTO|CFO|COO|CMO|the\s+\w+).*$/i, '');
  cleaned = cleaned.replace(/\s+for\s+(?:a|an|the)\s+.+$/i, '');
  cleaned = cleaned.replace(/\s+(?:and|&)\s+.+$/i, '');
  cleaned = cleaned.replace(/\//g, ' ');
  cleaned = cleaned.replace(/\s+/g, ' ').trim();
  cleaned = cleaned.replace(/[,.;:]+$/, '').trim();
  const words = cleaned.split(/\s+/).filter(Boolean);
  if (words.length >= 4) cleaned = words.slice(-2).join(' ');
  return cleaned;
}

let countryCodes = Array.isArray(input.country_codes) && input.country_codes.length > 0
  ? input.country_codes
  : input.country_code ? [input.country_code] : ['us'];
countryCodes = [...new Set(countryCodes.map(c => String(c).toLowerCase().trim()))].slice(0, 2);

const reportId = input.report_id || null;
const altTitlesDb = Array.isArray(input.alternate_titles_db) ? input.alternate_titles_db : [];
const rawTitle = input.career_title || '';
const cleanedTitle = cleanCareerTitle(rawTitle);
const nonEnglish = countryCodes.filter(c => !ENGLISH_LOCALES.has(c));

// Pre-format the country list for the prompt template (so the Set node stays
// simple: one expression interpolation, no loops).
const country_lines_for_prompt = nonEnglish
  .map(c => `- ${c}: ${COUNTRY_NAMES[c] || c}`)
  .join('\n');

// Forward user_languages so downstream scoring can use them
const userLanguages = Array.isArray(input.user_languages) ? input.user_languages : [];

return [{
  json: {
    raw_career_title: rawTitle,
    report_id: reportId,
    alternate_titles_db: altTitlesDb,
    user_languages: userLanguages,
    cleaned_career_title: cleanedTitle,
    country_codes: countryCodes,
    non_english_countries: nonEnglish,
    country_lines_for_prompt,
    location: input.location || '',
    work_arrangement: input.work_arrangement || 'any',
    job_commitment: input.job_commitment || 'any',
    avoid_preferences: Array.isArray(input.avoid_preferences) ? input.avoid_preferences : [],
    alt_titles_summary: altTitlesDb.length ? altTitlesDb.join('; ') : 'none',
    career_overview: typeof input.career_overview === 'string' ? input.career_overview : '',
    skip_translation: nonEnglish.length === 0 || !cleanedTitle
  }
}];

Build LinkedIn Search URL:
// Build LinkedIn search URLs in a single Apify-friendly batch.
// Includes both primary (translated per non-English country) AND alt-title
// URLs in ONE call so Apify can parallelize them internally — faster than
// running two sequential Apify calls (which hit the Cloudflare 100s timeout).
const items = $input.all();
const item = items[0]?.json || {};

const llmText = item.text || item.output || '';
let llmKeywords = [];
try {
  const cleaned = String(llmText).replace(/```(?:json)?/g, '').trim();
  const m = cleaned.match(/\{[\s\S]*\}/);
  if (m) {
    const parsed = JSON.parse(m[0]);
    llmKeywords = Array.isArray(parsed.keywords)
      ? parsed.keywords.map(k => String(k).trim()).filter(Boolean)
      : [];
  }
} catch (e) {
  console.warn('Keyword parse failed:', e.message);
}

const prep = $('Prepare Translation Input').first().json;
const cleanedTitle = prep.cleaned_career_title || '';
const rawTitle = prep.raw_career_title || '';
const countryCodes = prep.country_codes || ['us'];
const city = prep.location || '';
const workArrangement = prep.work_arrangement || 'any';
const F_WT_PARAM = { remote_only: '2', remote_friendly: '2,3' };
const wtParam = F_WT_PARAM[workArrangement];
const jobCommitment = prep.job_commitment || 'any';
const F_JT_PARAM = { full_time: 'F', part_time: 'P', contract: 'C' };
// Date posted survived LinkedIn's move to AI search as a real URL filter
// (f_TPR, in seconds), unlike the actor's `datePosted` input, which is ignored
// whenever `urls` is set. 30 days drops stale postings without starving niche
// searches: a 4-URL test returned the same 20 results, none older than 30 days,
// where the unfiltered run had included a 3-month-old posting.
const DATE_POSTED_WINDOW = 'r2592000'; // 30 days
const jtParam = F_JT_PARAM[jobCommitment];
const altTitlesDb = Array.isArray(prep.alternate_titles_db) ? prep.alternate_titles_db : [];

const ENGLISH_LOCALES = new Set(['us','gb','ca','au','nz','ie']);
const COUNTRY_NAMES = {
  us: 'United States', gb: 'United Kingdom', ca: 'Canada', au: 'Australia',
  nl: 'Netherlands', de: 'Germany', fr: 'France', be: 'Belgium',
  ch: 'Switzerland', at: 'Austria', ie: 'Ireland', se: 'Sweden',
  dk: 'Denmark', no: 'Norway', fi: 'Finland', es: 'Spain', it: 'Italy',
  pt: 'Portugal', pl: 'Poland', nz: 'New Zealand', sg: 'Singapore', in: 'India'
};

function detectSeniority(title) {
  if (/\b(executive\s+coach|executive\s+assistant|account\s+executive)\b/i.test(title)) return null;
  if (/\b(chief|cxo|cpo|cto|cfo|ceo|coo|cmo)\b/i.test(title)) return '5,6';
  if (/\b(director|vp|vice\s+president|head\s+of)\b/i.test(title)) return '5,6';
  if (/\b(senior|sr\.?|lead|principal|staff)\b/i.test(title)) return '4';
  if (/\b(junior|jr\.?|associate|entry|intern|graduate|trainee)\b/i.test(title)) return '2,3';
  return null;
}

const seniorityPrimary = detectSeniority(rawTitle);

// PRIMARY URLs: one per country, using translated keyword for non-English locales
const urls = [];
const searchTermsLog = [];
for (const code of countryCodes) {
  const countryName = COUNTRY_NAMES[code] || 'United States';
  const location = city ? `${city}, ${countryName}` : countryName;
  // LLM-generated English keyword (preserves "AI"/domain terms, drops fluff).
  // Falls back to the rule-based cleaned title if the LLM gave nothing usable.
  const keyword = llmKeywords[0] || cleanedTitle;

  let url = `https://www.linkedin.com/jobs/search/?keywords=${encodeURIComponent(keyword)}&location=${encodeURIComponent(location)}&position=1&pageNum=0&f_TPR=${DATE_POSTED_WINDOW}`;
  if (seniorityPrimary) url += `&f_E=${seniorityPrimary}`;
  if (wtParam) url += '&f_WT=' + encodeURIComponent(wtParam);
  if (jtParam) url += '&f_JT=' + encodeURIComponent(jtParam);
  urls.push(url);
  searchTermsLog.push({ country: code, kind: 'primary', keyword });
}

// ALT URLs: up to 2 alt titles, English keywords, per country.
// These broaden coverage for niche careers where the primary keyword doesn't
// match LinkedIn's typical job-posting language (e.g. 'Executive Coach' →
// 'Leadership Coach', 'Performance Coach').
const selectedAlts = altTitlesDb
  .map(t => String(t || '').trim())
  .filter(Boolean)
  .filter(t => t.toLowerCase() !== cleanedTitle.toLowerCase()) // skip if alt == primary
  .slice(0, 3); // use up to 3 alt titles so report-suggested variations actually surface

for (const alt of selectedAlts) {
  const seniorityAlt = detectSeniority(alt);
  for (const code of countryCodes) {
    const countryName = COUNTRY_NAMES[code] || 'United States';
    const location = city ? `${city}, ${countryName}` : countryName;
    let url = `https://www.linkedin.com/jobs/search/?keywords=${encodeURIComponent(alt)}&location=${encodeURIComponent(location)}&position=1&pageNum=0&f_TPR=${DATE_POSTED_WINDOW}`;
    if (seniorityAlt) url += `&f_E=${seniorityAlt}`;
    if (wtParam) url += '&f_WT=' + encodeURIComponent(wtParam);
  if (jtParam) url += '&f_JT=' + encodeURIComponent(jtParam);
    urls.push(url);
    searchTermsLog.push({ country: code, kind: 'alt', keyword: alt });
  }
}

// Apify's `count` is a GLOBAL budget shared by every URL, so the first URL ate
// almost all of it: in the 2026-08-05 run, 28 of 32 results came from one URL
// and 5 of the 8 URLs returned nothing, which silently defeated the alt-title
// searches below. `limitPerSource` caps each URL on its own, guaranteeing every
// alt title a share. `count` stays on as a hard ceiling for the total.
const PER_URL_LIMIT = 5;
const count = Math.max(10, Math.min(40, urls.length * PER_URL_LIMIT));

return [{
  json: {
    raw_career_title: rawTitle,
    cleaned_career_title: cleanedTitle,
    seniority_filter: seniorityPrimary,
    country_codes: countryCodes,
    work_arrangement: workArrangement,
    location: city,
    llm_keywords: llmKeywords,
    alt_titles_used: selectedAlts,
    search_terms_per_url: searchTermsLog,
    per_url_limit: PER_URL_LIMIT,
    apify_input: {
      urls,
      count,
      limitPerSource: PER_URL_LIMIT,
      scrapeCompany: false
    }
  }
}];
